        public byte[] bufferRead = new byte[4];

        public void SetProcessHandle(IntPtr handle)
        {
            _processHandle = handle;
        }

        public void SetBaseAddress(IntPtr baseAddress)
        {
            _baseAddress = baseAddress;
        }

        public IntPtr GetProcessHandle() => _processHandle;
        public IntPtr GetBaseAddress() => _baseAddress;

        Dictionary<string, int> aTypeSize = new Dictionary<string, int>
        {
            {"UChar", 1}, {"Char", 1},
            {"UShort", 2}, {"Short", 2},
            {"UInt", 4}, {"Int", 4},
            {"UFloat", 4}, {"Float", 4},
            {"Int64", 8}, {"Double", 8}
        };

        public void WriteRawMemory(IntPtr address, byte[] buffer, int writesize)
        {
            int pBytesWrite = 0;
            WriteProcessMemory(_processHandle, address, buffer, writesize, ref pBytesWrite);
        }

        public void ReadMemory(IntPtr address, ref byte[] buffer, int bytes, ref int pBytesRead)
        {
            ReadProcessMemory(_processHandle, address, buffer, bytes, ref pBytesRead);
        }

        public void ReadRawMemory(long address, ref byte[] buffer, int bytes = 4, params int[] aOffsets)
        {
            buffer = new byte[bytes];
            int pBytesRead = 0;

            try
            {
                ReadProcessMemory(_processHandle, (IntPtr)address, buffer, bytes, ref pBytesRead);
            }
            catch
            {
                // Log error if needed
            }
        }

        public string ReadMemString(long TPoint)
        {
            string name = "";
            for (int i2 = 0; i2 < 16; i2++)
            {
                if (ReadByteRaw((IntPtr)(TPoint + i2)) != 0x00)
                {
                    name += ReadUCharRaw((IntPtr)(TPoint + i2));
                }
                else
                {
                    break;
                }
            }
            return name;
        }

        public int ReadInt(IntPtr ThisAd)
        {
            int bytesRead = 0;
            bufferRead = new byte[aTypeSize["Int"]];
            ReadProcessMemory(_processHandle, (IntPtr)((long)_baseAddress + (long)ThisAd), bufferRead, aTypeSize["Int"], ref bytesRead);

            if (bytesRead > 0)
            {
                return BitConverter.ToInt32(bufferRead, 0);
            }
            return 0;
        }

        public UInt16 ReadUInt16(IntPtr ThisAd)
        {
            int bytesRead = 0;
            bufferRead = new byte[aTypeSize["Short"]];
            ReadProcessMemory(_processHandle, (IntPtr)((long)_baseAddress + (long)ThisAd), bufferRead, aTypeSize["Short"], ref bytesRead);

            if (bytesRead > 0)
            {
                return BitConverter.ToUInt16(bufferRead, 0);
            }
            return 0;
        }

