        {
            try
            {
                int bytesRead = 0;
                bufferRead = new byte[aTypeSize["Int"]];
                ReadProcessMemory(_processHandle, (IntPtr)((long)_baseAddress + (long)ThisAd), bufferRead, aTypeSize["Int"], ref bytesRead);

                if (bytesRead > 0)
                {
                    return BitConverter.ToUInt32(bufferRead, 0);
                }
            }
            catch { }
            return 0;
        }

        public Int32 ReadInt32(IntPtr ThisAd)
        {
            int bytesRead = 0;
            bufferRead = new byte[aTypeSize["Int"]];
            ReadProcessMemory(_processHandle, (IntPtr)((long)_baseAddress + (long)ThisAd), bufferRead, aTypeSize["Int"], ref bytesRead);

            if (bytesRead > 0)
            {
                return BitConverter.ToInt32(bufferRead, 0);
            }
            return 0;
        }

        public Int64 ReadInt64(IntPtr ThisAd)
        {
            int bytesRead = 0;
            bufferRead = new byte[aTypeSize["Int64"]];
            ReadProcessMemory(_processHandle, (IntPtr)((long)_baseAddress + (long)ThisAd), bufferRead, aTypeSize["Int64"], ref bytesRead);

            if (bytesRead > 0)
            {
                return BitConverter.ToInt64(bufferRead, 0);
            }
            return 0;
        }

        public unsafe UInt64 ReadUInt64(UIntPtr address)
        {
            int bytesRead = 0;
            byte[] buffer = new byte[8];
            IntPtr baseAddress = (IntPtr)address.ToPointer();
            ReadProcessMemory(_processHandle, baseAddress, buffer, buffer.Length, ref bytesRead);

            if (bytesRead > 0)
            {
                return BitConverter.ToUInt64(buffer, 0);
            }
            return 0;
        }

        public uint ReadUIntFromBuffer(byte[] bytes, uint offset, int size)
        {
            if (bytes == null)
            {
                throw new ArgumentNullException(nameof(bytes));
            }

            if (offset + size > bytes.Length)
            {
                throw new ArgumentOutOfRangeException(nameof(offset), "Offset and size exceed the length of the byte array.");
            }

            return BytesToUint(bytes, offset, size);
        }

        private static uint BytesToUint(byte[] bytes, uint offset, int size)
        {
            uint result = 0;

            for (int i = 0; i < size; i++)
